import { useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { format, parseISO } from 'date-fns'
import { id as idLocale } from 'date-fns/locale'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, PARTNER_VISIBILITY_OPTIONS, Sheet, VisibilityBadge } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, softDelete } from '@/db/db'
import type { Memory, Visibility } from '@/types/domain'
import { useT } from '@/i18n'

/** Momen (MEM-01) — the shared history that makes leaving the app costly. */
export default function Moments() {
  const t = useT()
  const { profile } = useSession()
  const me = profile?.id
  const [params, setParams] = useSearchParams()
  const [open, setOpen] = useState(params.get('baru') === '1')
  const memories = useOwned<Memory>('memories', me, (a, b) => b.date.localeCompare(a.date))

  if (!profile || !me) return null

  const byYear = new Map<string, Memory[]>()
  for (const m of memories ?? []) {
    const y = m.date.slice(0, 4)
    byYear.set(y, [...(byYear.get(y) ?? []), m])
  }

  function close() {
    setOpen(false)
    if (!params.has('baru')) return
    params.delete('baru')
    setParams(params, { replace: true })
  }

  return (
    <div className="stack">
      <div className="row row--between">
        <h1>{t('mem.title')}</h1>
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('mem.save')}
        </button>
      </div>
      <p className="card__hint">{t('mem.subtitle')}</p>

      {(memories ?? []).length === 0 ? (
        <Card>
          <EmptyState
            sticker="empty-wish"
            title={t('mem.empty')}
            hint={t('mem.emptyHint')}
            action={
              <button className="btn btn--sm" onClick={() => setOpen(true)}>
                {t('mem.saveFirst')}
              </button>
            }
          />
        </Card>
      ) : (
        [...byYear.entries()]
          .sort((a, b) => b[0].localeCompare(a[0]))
          .map(([year, items]) => (
            <Card key={year} title={year} icon="memories">
              <ul className="list">
                {items.map((m) => (
                  <li key={m.id} className="list__item">
                    <Icon name={m.isMilestone ? 'ring' : 'memories'} size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{m.title}</strong>
                      <span className="card__hint">
                        {format(parseISO(m.date), 'd MMMM', { locale: idLocale })}
                        {m.isMilestone ? ` · ${t('mem.milestoneLabel')}` : ''}
                      </span>
                      {m.story && <span className="card__hint">{m.story}</span>}
                    </span>
                    <VisibilityBadge visibility={m.visibility} />
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('memories', m.id, me)}>
                      <Icon name="close" size={16} label={t('common.deleteX', { name: m.title })} />
                    </button>
                  </li>
                ))}
              </ul>
            </Card>
          ))
      )}

      <NewMemory open={open} onClose={close} me={me} />
    </div>
  )
}

function NewMemory({ open, onClose, me }: { open: boolean; onClose: () => void; me: string }) {
  const t = useT()
  const [title, setTitle] = useState('')
  const [date, setDate] = useState(format(new Date(), 'yyyy-MM-dd'))
  const [story, setStory] = useState('')
  const [milestone, setMilestone] = useState(false)
  const [visibility, setVis] = useState<Visibility>('shared')

  async function save() {
    if (!title.trim()) return
    await db.memories.add({
      ...newEnvelope(me, 'C2_shared_ops', { visibility }),
      kind: 'memory',
      title: title.trim(),
      date,
      ...(story.trim() ? { story: story.trim() } : {}),
      isMilestone: milestone,
    } as never)
    setTitle('')
    setStory('')
    setMilestone(false)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('mem.save')}>
      <div className="stack">
        <Field label={t('mem.what')}>
          {(p) => <input {...p} type="text" value={title} onChange={(e) => setTitle(e.target.value)} />}
        </Field>
        <Field label={t('mem.when')}>{(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}</Field>
        <Field label={t('mem.story')} hint={t('common.optional')}>
          {(p) => <textarea {...p} value={story} onChange={(e) => setStory(e.target.value)} />}
        </Field>
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input
            type="checkbox"
            checked={milestone}
            onChange={(e) => setMilestone(e.target.checked)}
          />
          <span>{t('mem.milestone')}</span>
        </label>
        <Field label={t('common.whoCanSee')}>
          {(p) => (
            <select {...p} value={visibility} onChange={(e) => setVis(e.target.value as Visibility)}>
              {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                <option key={v} value={v}>
                  {t(`vis.opt.${v}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!title.trim()}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
